package dev.mixer.android;
import java.util.*;import java.util.function.Consumer;import android.app.Activity;import android.widget.EditText;import android.view.inputmethod.*;
/** Original expression is evaluated once; values/exceptions/counts/order remain exact for both attribute overloads. */
public final class AttributeOutcomeControls {
 private AttributeOutcomeControls(){}private static int checks;private static final String DESC="(Ljava/lang/CharSequence;ILandroid/view/inputmethod/TextAttribute;)Z";
 private static final class Fatal extends Error{private static final long serialVersionUID=1L;}
 private static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 private static boolean call(BaseInputConnection target,String family){return family.equals("commitText")?target.commitText("z",1,new TextAttribute()):target.setComposingText("z",1,new TextAttribute());}
 private static String name(String family){return "BaseInputConnection."+family+"WithAttributes";}
 private static EditText editor(){EditText edit=new EditText(new Activity());edit.setText("old");edit.setSelection(3,3);return edit;}
 private static void normal(String family,boolean initiallyClosed){
  EditText edit=editor();int[] filters={0};edit.setFilters(new android.text.InputFilter[]{(source,start,end,destination,dstart,dend)->{filters[0]++;return null;}});BaseInputConnection target=new BaseInputConnection(edit,true);target.closed=initiallyClosed;List<NativeOutcomeProbe.Outcome> rows=new ArrayList<>();List<String> order=new ArrayList<>();ConcreteHostProbe.reset();NativeOutcomeProbe.begin(value->{if(value.method().equals(name(family)))order.add("outcome");rows.add(value);});
  ConcreteHostProbe.hook=(method,phase)->{if(method.equals(name(family))&&phase.equals("beforeReturn")){order.add("ordinary");target.closed=!initiallyClosed;}};Consumer<ConcreteHostProbe.Event> observer=event->{if(event.method.equals(name(family))&&event.phase.equals("beforeReturn")){check(ConcreteHostProbe.count(event.method,event.phase)==1,"original count before qualification callback");order.add("qualification");}};ConcreteHostProbe.installQualificationHook(observer);boolean actual;try{actual=call(target,family);}finally{ConcreteHostProbe.clearQualificationHook(observer);ConcreteHostProbe.hook=null;NativeOutcomeProbe.end();}
  List<NativeOutcomeProbe.Outcome> own=rows.stream().filter(value->value.method().equals(name(family))).toList();check(actual==!initiallyClosed,"original boolean survives later closed-field change");check(own.size()==1&&own.get(0).completion().equals("return")&&own.get(0).descriptor().equals(DESC)&&own.get(0).receiver()==target&&own.get(0).value().equals(actual),"exact one original typed return/receiver");check(order.equals(List.of("ordinary","qualification","outcome")),"ordinary hook then qualification then measured return");check(filters[0]==(initiallyClosed?0:1),"insert/filter expression evaluated once");check(edit.getText().toString().equals(initiallyClosed?"old":"oldz"),"actual original text effect");check(ConcreteHostProbe.count(name(family),"entry")==1&&ConcreteHostProbe.count(name(family),"beforeReturn")==1&&NativeOutcomeProbe.clean(),"counts/closed lifetime preserved");ConcreteHostProbe.reset();
 }
 private static void exceptional(String family,boolean qualified,String phase,Throwable original){
  EditText edit=editor();BaseInputConnection target=new BaseInputConnection(edit,true);List<NativeOutcomeProbe.Outcome> rows=new ArrayList<>();ConcreteHostProbe.reset();NativeOutcomeProbe.begin(rows::add);Consumer<ConcreteHostProbe.Event> hook=event->{if(event.method.equals(name(family))&&event.phase.equals(phase))ConcreteHostProbe.fail(original);};if(qualified)ConcreteHostProbe.installQualificationHook(hook);else ConcreteHostProbe.hook=(method,at)->{if(method.equals(name(family))&&at.equals(phase))ConcreteHostProbe.fail(original);};Throwable escaped=null;
  try{call(target,family);}catch(RuntimeException|Error failure){escaped=failure;}finally{if(qualified)ConcreteHostProbe.clearQualificationHook(hook);ConcreteHostProbe.hook=null;NativeOutcomeProbe.end();}
  List<NativeOutcomeProbe.Outcome> own=rows.stream().filter(value->value.method().equals(name(family))).toList();check(escaped==original,"same original ordinary/fatal identity escapes");check(own.size()==1&&own.get(0).completion().equals("exception")&&own.get(0).originalException()==original&&own.get(0).receiver()==target,"same original exception captured with no invented return");check(edit.getText().toString().equals(phase.equals("entry")?"old":"oldz"),"unchanged branch/callback/exception ordering");check(ConcreteHostProbe.count(name(family),"entry")==1&&ConcreteHostProbe.count(name(family),"beforeReturn")== (phase.equals("entry")?0:1)&&NativeOutcomeProbe.clean(),"original hit count and explicit hook lifetime");ConcreteHostProbe.reset();
 }
 private static void captureFailure(String family){EditText edit=editor();BaseInputConnection target=new BaseInputConnection(edit,true);Fatal failure=new Fatal();ConcreteHostProbe.reset();NativeOutcomeProbe.begin(value->{if(value.method().equals(name(family)))throw failure;});check(call(target,family),"observer fatal cannot replace actual true result");NativeOutcomeProbe.end();boolean dirty=!NativeOutcomeProbe.clean();check(dirty&&NativeOutcomeProbe.captureFailure()==failure&&edit.getText().toString().equals("oldz"),"passive capture failure refuses original-preserving attempt");NativeOutcomeProbe.begin(value->{});NativeOutcomeProbe.end();check(NativeOutcomeProbe.clean()&&dirty,"next begin does not erase locally latched earlier refusal");ConcreteHostProbe.reset();}
 public static void main(String[] args){for(String family:List.of("commitText","setComposingText")){normal(family,false);normal(family,true);for(boolean qualified:new boolean[]{false,true})for(String phase:List.of("entry","beforeReturn")){exceptional(family,qualified,phase,new IllegalStateException("exact ordinary"));exceptional(family,qualified,phase,new Fatal());}captureFailure(family);}System.out.println("PASS exact two attribute-return wrappers checks="+checks);}
}
